from pathlib import Path
import hashlib,json
R=Path(r"\\192.168.87.201\Projects\RicochetAngles\01_RND\ThreeJSDEV")
original=R/'RicochetAngles_Legacy_ThreeJS_Spike.html'
s=original.read_text(encoding='utf-8')
s=s.replace('LEGACY · RENDERER SPIKE','LEGACY · M41 GLB STRESS SPIKE',1)
s=s.replace('<div id="spikeStatus">','<div id="glbStatus">M41 loading · Primitive fallback</div><div id="stressStatus">Stress Tanks: 0 · P: add one</div><button id="clearStress" type="button">Clear stress</button>\n  <div id="spikeStatus">',1)
s=s.replace("await import('https://cdn.jsdelivr.net/npm/three@0.160.1/build/three.module.js')","await import('./vendor/three.module.js')",1)
extension=json.loads(r'''"\n  const GLB_CONFIG={url:'../M41/export/M41_RND_v01.glb',unitsPerMeter:14};\n  const glbStatus=document.getElementById('glbStatus'),stressStatus=document.getElementById('stressStatus');\n  const stressGroup=new THREE.Group(); stressGroup.name='RENDERER_ONLY_STRESS'; scene.add(stressGroup);\n  const stressTanks=[];\n  let glbTemplate=null,glbPlayer=null,glbHull=null,glbTurret=null,footprint=null;\n  const playerMaterials=new Map();\n  function syncPlayerVisual() {\n    if(!glbPlayer){syncTank(playerVisual,game.player);return;}\n    const p=game.player;\n    glbPlayer.position.set(p.x,0,p.y);\n    glbHull.rotation.y=-p.angle;\n    glbTurret.rotation.y=-(p.turretAngle-p.angle);\n    for(const [m,base] of playerMaterials){\n      m.color.copy(base);\n      if(!p.alive)m.color.multiplyScalar(.35);\n      else if(p.hitFlash>0)m.color.lerp(new THREE.Color('#fff0bd'),.8);\n    }\n  }\n  function applyGLBShadow(root,on){root.traverse(o=>{if(o.isMesh){o.castShadow=on;o.receiveShadow=on;}});}\n  function updateStressLabel(){\n    const cols=footprint?Math.max(1,Math.floor((W-40)/footprint.sx)):0;\n    const rows=footprint?Math.max(1,Math.floor((H-130)/footprint.sz)):0;\n    stressStatus.textContent='Stress Tanks: '+stressTanks.length+' · P: add one'+\n      (stressTanks.length>cols*rows?' · grid exceeds viewport capacity ('+cols*rows+')':'');\n  }\n  function addStressTank(){\n    if(!glbTemplate){glbStatus.textContent='M41 not ready · Primitive player continues';return false;}\n    return withVisualRandom(()=>{\n      const tank=glbTemplate.clone(true); tank.name='StressM41_'+(stressTanks.length+1);\n      applyGLBShadow(tank,SPIKE_CONFIG.shadows);\n      stressGroup.add(tank);stressTanks.push(tank);updateStressLabel();return true;\n    });\n  }\n  function syncStressGrid(sx,sy){\n    if(!footprint)return;\n    const cols=Math.max(1,Math.floor((W-40)/footprint.sx));\n    stressTanks.forEach((t,i)=>t.position.set(\n      camera.x-sx+20-footprint.minX+(i%cols)*footprint.sx,\n      0,camera.y-sy+105-footprint.minZ+Math.floor(i/cols)*footprint.sz));\n  }\n  window.addEventListener('keydown',e=>{\n    if(e.code!=='KeyP'||e.ctrlKey||e.metaKey||e.altKey)return;\n    if(/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))return;\n    e.preventDefault();e.stopImmediatePropagation();addStressTank();\n  },true);\n  window.addEventListener('keyup',e=>{if(e.code==='KeyP'){e.preventDefault();e.stopImmediatePropagation();}},true);\n  document.getElementById('clearStress').onclick=()=>{\n    stressTanks.forEach(t=>stressGroup.remove(t));stressTanks.length=0;updateStressLabel();\n  };\n  async function loadM41(){\n    try{\n      const {GLTFLoader}=await import('./vendor/GLTFLoader.js');\n      const loader=withVisualRandom(()=>new GLTFLoader());\n      const gltf=await loader.loadAsync(GLB_CONFIG.url);\n      withVisualRandom(()=>{\n        const model=gltf.scene;\n        for(const name of ['M41_ROOT','HULL','TRACK_L','TRACK_R','TURRET_PIVOT','TURRET','GUN'])\n          if(!model.getObjectByName(name))throw Error('Missing node '+name);\n        if(gltf.animations.length)throw Error('Unexpected animation');\n        model.traverse(o=>{if(o.isSkinnedMesh)throw Error('Unexpected skin');});\n        model.scale.setScalar(GLB_CONFIG.unitsPerMeter);\n        applyGLBShadow(model,SPIKE_CONFIG.shadows);\n        model.updateMatrixWorld(true);\n        const bounds=new THREE.Box3().setFromObject(model),size=bounds.getSize(new THREE.Vector3());\n        footprint={minX:bounds.min.x,minZ:bounds.min.z,sx:size.x*1.35,sz:size.z*1.45,size:size.toArray()};\n        glbTemplate=model;\n        glbPlayer=model.clone(true);glbPlayer.name='M41_PLAYER_VISUAL';\n        const copies=new Map();\n        glbPlayer.traverse(o=>{if(o.isMesh){\n          if(!copies.has(o.material)){const m=o.material.clone();copies.set(o.material,m);playerMaterials.set(m,m.color.clone());}\n          o.material=copies.get(o.material);\n        }});\n        glbHull=glbPlayer.getObjectByName('HULL');glbTurret=glbPlayer.getObjectByName('TURRET_PIVOT');\n        scene.remove(playerVisual.root);scene.add(glbPlayer);\n        glbStatus.textContent='M41 GLB ready · 14 legacy units/m · +X forward';\n        rendererSpike.glb={player:glbPlayer,template:glbTemplate,hull:glbHull,turret:glbTurret,footprint,config:GLB_CONFIG};\n        updateStressLabel();\n      });\n    }catch(error){glbStatus.textContent='M41 load failed · Primitive fallback: '+error.message;console.warn('M41 fallback',error);}\n  }\n"''')
s=s.replace('  function syncPlayerVisual() { syncTank(playerVisual,game.player); }',extension,1)
s=s.replace('syncProjectileVisuals(); syncCamera(sx,sy);','syncProjectileVisuals(); syncCamera(sx,sy); syncStressGrid(sx,sy);',1)
s=s.replace('playerVisual,bossVisual,\n','playerVisual,bossVisual,stressTanks,stressGroup,addStressTank,\n',1)
s=s.replace("(SPIKE_CONFIG.cameraElevation===90?'':' · 높이 시차 있음 / 판정은 원본 2D');","(SPIKE_CONFIG.cameraElevation===90?'':' · 높이 시차 있음 / 판정은 원본 2D')+' · '+stats.triangles+' triangles · Shadow '+(stats.shadows?'ON':'OFF');",1)
s=s.replace('    scene.traverse(o=>{if(o.material)o.material.needsUpdate=true;});','    if(glbTemplate)applyGLBShadow(glbTemplate,e.target.checked);\n    if(glbPlayer)applyGLBShadow(glbPlayer,e.target.checked);\n    applyGLBShadow(stressGroup,e.target.checked);\n    scene.traverse(o=>{if(o.material)o.material.needsUpdate=true;});',1)
s=s.replace("  renderer.domElement.addEventListener('webglcontextlost'","  loadM41();\n  renderer.domElement.addEventListener('webglcontextlost'",1)
out=R/'spike/RicochetAngles_Legacy_ThreeJS_GLBSPIKE.html'
assert not out.exists()
out.write_text(s,encoding='utf-8')
a=original.read_text(encoding='utf-8').split('<script>')[1].split('</script>')[0]
b=s.split('<script>')[1].split('</script>')[0]
assert a==b
(R/'M41/notes/code_preservation.json').write_text(json.dumps({'classic_script_byte_equivalent':a==b,'source_sha256':hashlib.sha256(original.read_bytes()).hexdigest(),'gameplay_script_sha256':hashlib.sha256(a.encode()).hexdigest()},indent=2))
print('Created',out,'gameplay script identical:',a==b)

